SELECT gen_random_uuid()::text, 'formula', '$\text{GPR} = I_GR_g$', 'Ground Potential Rise', '$\text{GPR} = I_GR_g,\qquad I_G = S_fD_f(3I_0)$', '$\text{V}$', 'How far the substation grid rises above remote earth during a ground fault (IEEE 80).', '[{"symbol":"$I_G$","meaning":"current flowing from the grid to remote earth","unit":"$\\text{A}$"},{"symbol":"$R_g$","meaning":"grid resistance","unit":"$\\Omega$"},{"symbol":"$S_f$","meaning":"split factor (share not returning by shield wires)","unit":null},{"symbol":"$D_f$","meaning":"decrement factor for dc offset","unit":null}]'::jsonb, 'If GPR is below the tolerable touch voltage the design is safe without further checks.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Distribution Systems & Substation Design' AND t."subject" = 'EE' AND s."normKey" = 'substation grounding' AND s."active"), NULL, false, 'PENDING', now(), now()
