SELECT gen_random_uuid()::text, 'formula', '$E_m = \frac{\rho K_mK_iI_G}{L_M}$', 'Mesh Voltage', '$E_m = \frac{\rho K_mK_iI_G}{L_M}$', '$\text{V}$', 'The worst touch voltage inside a grid mesh, compared with the tolerable touch voltage.', '[{"symbol":"$\\rho$","meaning":"soil resistivity","unit":"$\\Omega\\text{·m}$"},{"symbol":"$K_m, K_i$","meaning":"spacing and irregularity factors","unit":null},{"symbol":"$L_M$","meaning":"effective buried length","unit":"$\\text{m}$"},{"symbol":"$I_G$","meaning":"grid current","unit":"$\\text{A}$"}]'::jsonb, 'Closer conductor spacing lowers K_m and the mesh voltage.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Distribution Systems & Substation Design' AND t."subject" = 'EE' AND s."normKey" = 'substation grounding' AND s."active"), NULL, false, 'PENDING', now(), now()
