SELECT gen_random_uuid()::text, 'formula', '$d = \sqrt{H(2R - H)} - \sqrt{y(2R - y)}$', 'Rolling-Sphere Protected Distance', '$d = \sqrt{H(2R - H)} - \sqrt{y(2R - y)}\quad (H \le R)$', '$\text{m}$', 'How far from a mast an object of height y is protected by the rolling-sphere method.', '[{"symbol":"$H$","meaning":"mast or shield height","unit":"$\\text{m}$"},{"symbol":"$y$","meaning":"height of the object to protect","unit":"$\\text{m}$"},{"symbol":"$R$","meaning":"sphere radius (striking distance)","unit":"$\\text{m}$"}]'::jsonb, 'A smaller sphere (lower stroke current) protects less: design for the striking distance of the smallest dangerous stroke.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Distribution Systems & Substation Design' AND t."subject" = 'EE' AND s."normKey" = 'lightning protection' AND s."active"), NULL, false, 'PENDING', now(), now()
