SELECT gen_random_uuid()::text, 'formula', '$N = \frac{N_g(b + 28h^{0.6})}{10}$', 'Strikes to an Overhead Line', '$N = \frac{N_g(b + 28h^{0.6})}{10}\ \text{per 100 km per year (Eriksson)}$', NULL, 'How many flashes an overhead line attracts per 100 km per year.', '[{"symbol":"$N_g$","meaning":"ground flash density","unit":"$\\text{1/km}^2\\text{/yr}$"},{"symbol":"$b$","meaning":"distance between outer conductors or shield wires","unit":"$\\text{m}$"},{"symbol":"$h$","meaning":"conductor height at the tower","unit":"$\\text{m}$"}]'::jsonb, 'Taller lines collect more strikes, roughly as h^0.6.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Distribution Systems & Substation Design' AND t."subject" = 'EE' AND s."normKey" = 'lightning protection' AND s."active"), NULL, true, 'PENDING', now(), now()
