SELECT gen_random_uuid()::text, 'formula', '$\text{SAIDI} = \frac{\sum r_iN_i}{N_T}$', 'SAIFI and SAIDI', '$\text{SAIFI} = \frac{\sum N_i}{N_T},\qquad \text{SAIDI} = \frac{\sum r_iN_i}{N_T}\quad (\text{IEEE 1366})$', NULL, 'How often, and for how long in total, the average customer is interrupted in a year.', '[{"symbol":"$N_i$","meaning":"customers interrupted by event i","unit":null},{"symbol":"$r_i$","meaning":"restoration time of event i","unit":"$\\text{min}$"},{"symbol":"$N_T$","meaning":"total customers served","unit":null}]'::jsonb, 'Count sustained interruptions only (over 5 minutes); momentary ones go in MAIFI.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Distribution Systems & Substation Design' AND t."subject" = 'EE' AND s."normKey" = 'reliability indices' AND s."active"), NULL, true, 'PENDING', now(), now()
