SELECT gen_random_uuid()::text, 'formula', '$\text{CAIDI} = \frac{\text{SAIDI}}{\text{SAIFI}}$', 'CAIDI and ASAI', '$\text{CAIDI} = \frac{\text{SAIDI}}{\text{SAIFI}},\qquad \text{ASAI} = 1 - \frac{\text{SAIDI}}{8760 \times 60}$', NULL, 'The average length of one interruption, and the fraction of the year service was available.', '[{"symbol":"$\\text{SAIDI}$","meaning":"average interruption minutes per customer","unit":"$\\text{min}$"},{"symbol":"$\\text{SAIFI}$","meaning":"average interruptions per customer","unit":null}]'::jsonb, 'CAIDI is a restoration-speed measure: a utility can improve SAIFI and make CAIDI look worse.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Distribution Systems & Substation Design' AND t."subject" = 'EE' AND s."normKey" = 'reliability indices' AND s."active"), NULL, true, 'PENDING', now(), now()
