SELECT gen_random_uuid()::text, 'formula', '$A = \frac{\text{MTBF}}{\text{MTBF} + \text{MTTR}}$', 'Availability from MTBF and MTTR', '$A = \frac{\text{MTBF}}{\text{MTBF} + \text{MTTR}};\qquad \text{series: } \prod A_i;\quad \text{parallel: } 1 - \prod(1 - A_i)$', NULL, 'The fraction of time a component, or a chain or set of them, is in service.', '[{"symbol":"$\\text{MTBF}$","meaning":"mean time between failures","unit":"$\\text{h}$"},{"symbol":"$\\text{MTTR}$","meaning":"mean time to repair","unit":"$\\text{h}$"}]'::jsonb, 'Series chains are weaker than their weakest part; redundancy (parallel) multiplies the UNavailabilities.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Distribution Systems & Substation Design' AND t."subject" = 'EE' AND s."normKey" = 'reliability indices' AND s."active"), NULL, true, 'PENDING', now(), now()
