SELECT gen_random_uuid()::text, 'formula', '$\cos\theta \ge 0.85 \implies Q \le 0.62P$', 'PDC Minimum Power Factor', '$\cos\theta \ge 0.85\ \text{lagging} \implies Q \le P\tan(\cos^{-1}0.85) = 0.62P$', NULL, 'The Philippine Distribution Code requires users to keep at least 0.85 lagging power factor at the connection point.', '[{"symbol":"$P$","meaning":"real power at the connection point","unit":"$\\text{kW}$"},{"symbol":"$Q$","meaning":"reactive power drawn","unit":"$\\text{kvar}$"}]'::jsonb, 'Below the DU''s target pf, penalties may apply; correct with capacitors sized by P(tanθ₁ − tanθ₂).', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Distribution Systems & Substation Design' AND t."subject" = 'EE' AND s."normKey" = 'philippine distribution code' AND s."active"), NULL, true, 'PENDING', now(), now()
