SELECT gen_random_uuid()::text, 'formula', '$\text{VUF} = \frac{V_2}{V_1} \times 100\%$', 'Voltage Unbalance Factor', '$\text{VUF} = \frac{V_2}{V_1} \times 100\% \approx \frac{\max|V_k - V_{avg}|}{V_{avg}} \times 100\%\quad (\text{PDC} \le 2.5\%)$', NULL, 'How unbalanced the three voltages are; the PDC caps it at 2.5% at the connection point in normal operation.', '[{"symbol":"$V_1, V_2$","meaning":"positive- and negative-sequence voltages","unit":"$\\text{V}$"},{"symbol":"$V_k, V_{avg}$","meaning":"the three LINE voltages and their average (NEMA approximation)","unit":"$\\text{V}$"}]'::jsonb, 'Small voltage unbalance makes several times as much current unbalance in motors.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Distribution Systems & Substation Design' AND t."subject" = 'EE' AND s."normKey" = 'philippine distribution code' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Distribution Systems & Substation Design' AND t."subject" = 'EE'
