SELECT gen_random_uuid()::text, 'formula', '$\text{THD} = \frac{\sqrt{\sum V_h^2}}{V_1}$', 'THD and TDD Limits', '$\text{THD}_V = \frac{\sqrt{\sum_{h \ge 2}V_h^2}}{V_1} \le 5\%,\qquad \text{TDD} = \frac{\sqrt{\sum_{h \ge 2}I_h^2}}{I_L} \le 5\%\quad (\text{PDC})$', NULL, 'The PDC''s harmonic limits: voltage distortion and current distortion (relative to maximum demand current).', '[{"symbol":"$V_h, I_h$","meaning":"harmonic voltages and currents","unit":"$\\text{V}$"},{"symbol":"$V_1$","meaning":"fundamental voltage","unit":"$\\text{V}$"},{"symbol":"$I_L$","meaning":"maximum demand load current","unit":"$\\text{A}$"}]'::jsonb, 'TDD divides by the maximum demand current, not the present fundamental, so light loads aren''t penalized.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Distribution Systems & Substation Design' AND t."subject" = 'EE' AND s."normKey" = 'philippine distribution code' AND s."active"), NULL, true, 'PENDING', now(), now()
